tool.example:
Input: {"server": "24Retail", "only_analyzed": false, "return_summaries": true}
Output: [
  {
    "name": "Compensation",
    "is_analyzed": true,
    "summary": "Cube contains employee compensation data..."
  },
  {
    "name": "Revenue",
    "is_analyzed": false,
    "summary": null
  }
]

Input: {"server": "24Retail", "query": "how many phones did we sell in 2022"}
Output: [
  {
    "cube_name": "Revenue",
    "cube_summary": "Cube contains retail data tracking sales of electronics like PCs and phones across time"
  }
]

Input: {
  "server": "24Retail",
  "query": "Show Q4 2025 budget vs actual for total company",
  "max_rows": 20,
  "max_columns": 8
}
Output: {
  "cube_name": "Compensation",
  "filters": "| Dimension | Value |\n| Month | Q4 |\n| Year | 2025 |",
  "data": "markdown table with results",
  "explanation": "System selected Q4 in Month dimension...",
  "state": "encoded_state_string"
}

Input: {
  "server": "24Retail",
  "cube": "Revenue",
  "mdx": "SELECT {[product].[product].[Phones],[product].[product].[PCs]} ON COLUMNS, {[Version].[Version].[Budget],[Version].[Version].[Actual]} ON ROWS FROM [Revenue] WHERE ([organization].[organization].[Total Company],[Month].[Month].[Q4],[Year].[Year].[Y1])"
}
Output: {
  "data": "| | 20000 | 30000 |\n| Version 1 | 6,154,989 | 12,790,444 |\n| Actual | 5,956,715 | 12,145,066 |",
  "state": "encoded_state_string"
}

Input: {"server": "24Retail", "cube": "Revenue", "query": "Show sales in may 2023"}
Output: {
  "cube_name": "Revenue",
  "mdx": "SELECT { [product].[product].[phones], [product].[product].[laptops] } ON 0, { [region].[region].[Europe] } ON 1 FROM [Revenue] WHERE ([month].[month].[may], [Year].[Year].[2023])",
  "state": "encoded_state_string"
}
